<?php
declare(strict_types=1);namespace BSPResearch;require __DIR__.'/model.php';$passed=0;$failed=0;function test($name,$fn){global $passed,$failed;try{$fn();$passed++;echo "PASS $name\n";}catch(\Throwable $e){$failed++;echo "FAIL $name: {$e->getMessage()}\n";}}function check($ok,$m='assertion failed'){if(!$ok)throw new \RuntimeException($m);}function recipe($id='escape'){return json_decode(encode(presets()[$id]['plan']),true);}function reject($p){try{normalize($p);throw new \RuntimeException('Invalid plan accepted');}catch(\InvalidArgumentException $e){}}
foreach(models() as $id=>$m)test('native solver parity '.$id,function()use($id,$m){$p=plan('Parity','Compare native solver.',[['Case',$id,[]]]);$r=evaluate(json_decode(encode($p),true));$v=$m['kind']==='foundation'?\solve($m['id']):\calc($m['id']);check($r['runs'][0]['result']===$v);check(count($r['comparisons'])===0);foreach($r['runs'][0]['result']['rows'] as $row)foreach($row as $n)check(is_finite((float)$n));});
foreach(presets() as $id=>$preset)test('preset deterministic '.$id,function()use($id){$p=recipe($id);$a=evaluate($p);$b=evaluate($p);check($a===$b);check(count($a['runs'])===count($p['cases']));$h=$a['result_sha256'];unset($a['result_sha256']);check(hash('sha256',encode($a))===$h);});
test('normalize default parameters and evidence ordering',function(){$p=recipe();$r=evaluate($p);$p['evidence']=array_reverse(array_merge($p['evidence'],[$p['evidence'][0]]));$p['cases'][0]['parameters']['duration']=12;check(evaluate($p)===$r);});
test('only same-model differences',function(){$r=evaluate(recipe('wall'));check(count($r['comparisons'])===1);check($r['comparisons'][0]['model']==='evidence:wall');check($r['comparisons'][0]['reference_case']==='case-1');check($r['comparisons'][0]['candidate_case']==='case-2');});
test('numeric delta and categorical omission',function(){$r=evaluate(recipe());foreach($r['comparisons'] as $c){foreach($c['metrics'] as $m)check($m['delta']===(is_numeric($m['reference'])&&is_numeric($m['candidate'])?$m['candidate']-$m['reference']:null));check($c['metrics'][0]['delta']===null);}});
test('critical escape versus reversible null',function(){$r=evaluate(recipe());check(abs($r['runs'][0]['result']['metrics'][1]['value'])<1e-12);check($r['runs'][1]['result']['metrics'][1]['value']>.99);});
test('wall conflict not hidden',function(){$r=evaluate(recipe('wall'));check($r['runs'][0]['result']['metrics'][3]['value']==='No feasible interval');});
test('auto linked records and gates retain source status',function(){$r=evaluate(recipe());$ids=array_column($r['evidence'],'id');check(in_array('escape-criterion',$ids,true));foreach($r['gates'] as $g)check($g['status']==='Completion not established in Review 6.0');foreach($r['evidence'] as $v)check($v['status']===\records()[$v['id']]['status']);});
test('provenance source hashes',function(){foreach(provenance()['source_files_sha256'] as $file=>$hash)check(hash_file('sha256',dirname(__DIR__,2).'/'.$file)===$hash);});
test('one to eight cases allowed',function(){$p=recipe();$p['cases']=array_fill(0,8,$p['cases'][0]);$r=evaluate($p);check(count($r['runs'])===8&&count($r['comparisons'])===7);});
test('step callback exact order',function(){$events=[];evaluate(recipe(),function($type,$name)use(&$events){$events[]=[$type,$name];});check($events===[['STEP_STARTED','case-1'],['STEP_FINISHED','case-1'],['STEP_STARTED','case-2'],['STEP_FINISHED','case-2'],['STEP_STARTED','case-3'],['STEP_FINISHED','case-3']]);});
foreach(['schema','title','question','cases','evidence'] as $key)test('reject wrong '.$key,function()use($key){$p=recipe();$p[$key]=false;reject($p);});
foreach(['unknown model','unknown parameter','null parameter','string numeric','outside bounds','nine cases','empty cases','forged results','unknown evidence','object evidence','control characters','oversize title','invalid case label','list parameters'] as $name)test('reject '.$name,function()use($name){$p=recipe();switch($name){case 'unknown model':$p['cases'][0]['model']='bad';break;case 'unknown parameter':$p['cases'][0]['parameters']['bad']=0;break;case 'null parameter':$p['cases'][0]['parameters']['ratio']=null;break;case 'string numeric':$p['cases'][0]['parameters']['ratio']='4';break;case 'outside bounds':$p['cases'][0]['parameters']['ratio']=17;break;case 'nine cases':$p['cases']=array_fill(0,9,$p['cases'][0]);break;case 'empty cases':$p['cases']=[];break;case 'forged results':$p['results']=[];break;case 'unknown evidence':$p['evidence']=['fake'];break;case 'object evidence':$p['evidence']=['foo'=>'escape-criterion'];break;case 'control characters':$p['title']="bad\nline";break;case 'oversize title':$p['title']=str_repeat('a',161);break;case 'invalid case label':$p['cases'][0]['label']='';break;case 'list parameters':$p['cases'][0]['parameters']=[1];break;}reject($p);});
echo "$passed passed, $failed failed\n";exit($failed?1:0);
